BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (203::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'ad53f2c372ef0fd57558a9a1b9338346f46b61f210fabae5de89fee7e23c7474'::TEXT, ARRAY[922, 630, 604]::BIGINT[]),
    (203::BIGINT, 'Es muy fácil pasar, es MUY suave calificando. Meta con ella si no quiere ir a clases. Las clases presenciales son de teoría, las virtuales de ejercicios (viernes, es cómodo). No es mala, pero las clases no ayudan mucho. Practique y entienda, ella si deja material que ayuda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '23c0cd13b22cf98cba9e8b51a0be4928daa41489931d1b9fd6177b3157439e8c'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'La profe puede verse seria, pero en realidad es bastante llevadera. Si usted sabe como caerle bien, hasta ganas le van a dar de ir a clases. Ayuda bastante durante la clase y en el teams responde rápido las dudas. Califica suave, es muy buena profe para llevarlo en Lab de fisica.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-21T00:00:00+00:00'::TIMESTAMPTZ, '85c116a21b5805160905f3cb58a28ab89fc94678604f38fc9eeb4178f3a609bb'::TEXT, ARRAY[607]::BIGINT[]),
    (203::BIGINT, 'Si uno se toma el tiempo, se da cuenta que es buena nota. Aunque suele decir comentarios chocantes, si ella ve que uno le pone, puede que le ayude en algo. Califica súper suave, recomendada si lo lleva por segunda vez. Si lo lleva de buenas a primeras sí va a tener que estudiar más.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Da crédito extra']::TEXT[], '2025-12-18T00:00:00+00:00'::TIMESTAMPTZ, '65dffd5357eddfd7b71c4a4c26fe6a64c0d40cc204b99b65ea6c47972e04beb7'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Califica demasiado suave, al final sin importar qué tan bueno sea el profesor en este curso se debe ser autodidacta. Con que ella vea que uno hizo parte de las OE da el 100 en esas evaluaciones'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '054ffb26434f6cefb6fcdcc5c9b9ecbfcb4f4dbfb25a92f5c9e9e56f2e87a967'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Sus clases suelen ser cortas pero precisas, enseña lo justo pero claro, el estudiante también debe estudiar por su cuenta. Califica súper suave y eso ayuda mucho. Intenta ayudar al estudiante pero tampoco espere que le regale la nota. Aveces puede sonar medio tosca al hablar, pero no busca ofender.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '933fc7ba5fd03f7cc6872c5a5eb4e03b970c760be36ddda268661727bb08484c'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Esta profe es todo un caso, llegaba muy tarde a las clases (como hasta 20 minutos después de la hora de inicio) y las clases si se le pueden llamar así, era ella haciendo un medio resumen de los capítulos del libro. Lo único bueno es que efectivamente califica suave, la recomiendo si está repitiendo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'e608c82452d0e8ae9872b65d94f5d0e5e7cf24dd568d9a3633d1aafae4098234'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Como persona es super buena nota y tira comentarios graciosos, pero practicamente usted tiene que ser su propio profesor, ya que no explica mucho en clase. A pesar de todo, califica suave e intenta ayudar al estudiante, entonces puede ser una buena opción si usted es totalmente autodidacta'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2025-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd27aa7463fed5a49bd5f0a9db12b2b1cf6cb9bf59e250270d704f5980550e0ce'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Sólo meta con ella si usted puede ser autodidacta, ella da bastante material pero casi no explica materia. Al menos califica suave y sus evaluaciones específicas no son difíciles de lograr.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, '340ea00e20ff78eed980755a834434a58b28626d06a790f6f1fc69c969106f36'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Horible nunca matriculen con ella, practicamente es como no tener profesor'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-20T00:00:00+00:00'::TIMESTAMPTZ, '0b7ae15d6f00921ae57ac462afd09949d5b455976e1371ac7f1c49925469f547'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Se pasa fácil porque las evaluaciones son sencillas y califica suave pero explica mal, los apuntes en la pizarra son muy desordenados y casi que toca trabajar solo porque si uno pregunta le hace mala cara o explica sin ganas'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'b25a0369c2b5210f3cc19bf28f90b8fbdf08b2e4439fd2381c26f369b9a2a188'::TEXT, ARRAY[607]::BIGINT[]),
    (203::BIGINT, 'Pésima opción si usted lo está llevando por primera vez. La clase es sentarse y responder preguntas del libro. Cuando le da la gana explicar lo hace decente, pero casi nunca lo hace. Eso sí, las evaluaciones de ella son fáciles y califica bastante suave.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2025-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'a5926e1e6801814266028642535e63f4ce4ca9018cfe30daa104fa2ca37ced5a'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'La profe es demasiado divertida, explica lo justo para trabajar, pero cuando uno le hace alguna pregunta le explica súper claro. Volvería a llevar algún lab con ella'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'b0ffd0cbd5d38b3321fca20678527aae394ca05c593838bcf4f0d0238840bb3e'::TEXT, ARRAY[607]::BIGINT[]),
    (203::BIGINT, 'Siempre llega tarde, casi no se le entiende al explicar y solo copia y pega en la pizarra lo que hay en el libro de consulta, califica como debe pero tarda demasiado en dar las notas. No la recomiendo, si es su única opción, prepárese para ser doble autodidacta.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-27T00:00:00+00:00'::TIMESTAMPTZ, 'd56f0d0f797eef9bdd9a3b1fab223ae12d652f3fefd0755ccd302be75f48df73'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'Mae NO, solo no matriculen con ella. Fisica II es un curso autodidacta, pero con ella es como si no tuvieran profe en absoluto.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-03-18T00:00:00+00:00'::TIMESTAMPTZ, '2de4043cd7a67d669ed6c0f4c30765297c67d115bf14de1ef219ebde042c1129'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Unos comentarios dicen que califica suave, pero la verdad no, califica cómo debe ser, pero no da puntos ni nada por el estilo. Explica muy bien eso sí aunque es weird as F* man, tiene un mood muy cambiante y de eso depende cómo ande para las clases y calificar. Opción masomenos'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-14T00:00:00+00:00'::TIMESTAMPTZ, '4164549099e910e916fc09a5d2d95a8f4334b9d562bae608476f5fb8730591d9'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'Es una mae rara, es como que pura vida, pero a veces tiene un mood de sh**, explica decente, aunque depende de cómo ande. Califica justo y las evaluaciones de ella son puntos easy porque hasta virtuales son, es opción a considerar. No pasa lista.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-09T00:00:00+00:00'::TIMESTAMPTZ, '4e59ef3340002ae1102a46fd56b2163d9ff493275f7b801f5963b75a729949b4'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'No dude en llevar con ella. Muy buena persona, califica suave, ayuda mucho, si uno le escribe siempre responde y busca aclarar todo lo que pueda, eso si, si uno la busca. Considero que es mejor para Física II hace un poco más de material que para Física III.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Brinda apoyo']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'dfb99bc42ef4471e45dced026d2f38ae9a59aee9dca92d9676ee0592902ff005'::TEXT, ARRAY[922]::BIGINT[]),
    (203::BIGINT, 'te amo jennifer la escuela de física se cae a pedazos pero vos la levantás, vos sacás adelante a los grupos. si no fuera por vos tendría que repetir física 2 seguro con algún otro profe de esa escuela'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2024-10-15T00:00:00+00:00'::TIMESTAMPTZ, 'b08c95387d45ba65f39046a354e7e35fd369e50ac135ab754b3762904b34fa6f'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'who is this DIVA ????'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-10-06T00:00:00+00:00'::TIMESTAMPTZ, '05cbac2e83968159d8a251514d4f8aee89092949e5c87e7eda91ebbdaa302f1f'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-10-02T00:00:00+00:00'::TIMESTAMPTZ, 'fc12c38c9965648c6aee218d60a857c2db4e4fd3a577f90403139867b403e245'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'Es un toque perezosa, a veces no llega a la clase sin decir absolutamente nada, pero la mayoría del tiempo es buena profe y explica bien. Las evaluaciones que hace usualmente son sencillas y revisa suave.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'b9c835ed97817d9f084f2ba26d80e00775ceff378eb3592364acc2b2c2431e32'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Como profesora explica bien cuando anda con ganas, muchas veces anda con pereza y tira comentarios chistoso. Las evaluaciones las califica muy fácil y se ganan solas. Los exámenes los califica suave. Hay que estudiar bastante por aparte pero ya es por el curso, sin embargo la profe está bastante bie'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a82bbdc93e1b915f1234dd8dfa32d1be009f5bdff87310d96b7a39c304eb1d4c'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Muy mala profesora, sus clases no sirven de nada, deja trabajos que son para perder el tiempo, casi no hace ejercicios y se le ve nulo interés, es odiosa y muy mediocre. No es de asistencia obligatoria. califica suave. Recomendada si a repetido curso, si quiere aprender EVITELA'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'bbfe11331926b5ae9234bb57cc8500afa1ae73d62eb4261ee717f9afda9b4ccb'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Si están repitiendo el curso, matriculen con ella, revisa exámenes muy por encima. Es un curso bastante demandante en cuanto a densidad de materia y práctica, si es su primera vez, ella no es la mejor opción. Es bastante odiosa y siempre se pierden como 40min de clase.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '53cbc94b979a9b3cdbeb8682c2536743c9761968f263b6f1502265e05a5c4411'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'La profe tiene una actitud pesada, como de que no tiene ganas ni de existir. Sus clases se basan en hacer un resumen del libro y la teoría queda clara, pero, hace muy pocos ejercicios (que son lo realmente importante). Califica muy suave los examenes, el 10% de ella es fácil obtenerlo. Pongale usted'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '7d21475e6620c140b1cd643ec8a75c2b7b10e1a13c7f3549a68733748b095f78'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Es buena persona, pero tiene un carácter fuerte. Es buena explicando, hace un resumen del libro. No hace muchos ejercicios. Los exámenes los califica bastante suave. El 10% de asignaciones es muy fácil ganarlo. De vez en cuando hace comentarios vacilones. No pasa asistencia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'b7547109e525c9a0af113494c485c719074965c2b929b4c841cfe18d001e78e9'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Personalmente nunca entendía que era lo que estaba explicando, tuve que ser full autodidacta. Califica suave y en el fondo es buena persona, pero por alguna razón se esfuerza en parecer tosca. Es mejor que la mayoría de alternativas'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '2a3f816eae6f2ffd367734bb9e917881a107e2eb335f1053daf2202c921914f4'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Hace buenos resúmenes del libro a la hora de dar la clase, también hace buenos ejercicios de práctic durante la clase. Aunque aveces realiza actividades un poco aburridas cuando pide hacer resúmenes, son útiles. Es buena gente calificando'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e2f1475bc5cdb51dbcffd03cbb9df78285e8a7b5d31602f56ccb52f2738a06a2'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Puede parecer y a veces es odiosa, pero en verdad es buena gente. No parece muy interesada por el curso en general y se nota en sus explicaciones, pero el curso es sencillo y evalúa muy suave, pero si espera buenos informes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '69aff882fed699193c6b4dfb4787b386d02f1e68e127676605010f78ea0938f0'::TEXT, ARRAY[607]::BIGINT[]),
    (203::BIGINT, 'La materia no es difícil, pero la falta de claridad, ejemplos y explicaciones lo vuelve una pesadilla. Si usted quiere aprender no matricule con ella, pasará más tiempo extra memorizando teoría y procesos, tiempo que debería invertirse en pensar y analizar, no a aprender lo que se supone es de clase'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '76ae2feabd1645f94eb84a9fed344be31f4fdf467066dafced74b9da41e00ebe'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'di estudie y le va bien. me tocó repetir el curso y lo llevé con ella y por fin entendí. califica suave y en clase se hacen ejemplos parecidos al examen. el resto de evaluaciones casi que las regala así que solo pongale en exámenes y quices.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'ceb2a0113acb5b57a2574373168792a78265543cf8a1defca13fa1924e20191e'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Las clases siempre terminan antes, a veces parece que da la clases sin ganas o con pereza, puede parecer un poco "odiosa". Eso sí, califica muy suave, las evalucaiones "Otras" y el proyecto casi las regala, las tareas son de cátedra y aveces no son claras, los exámenes son fáciles.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '59e606c295d0d15f4b0e2d96c69222a687459391e39e76cb5512f124cc7860bb'::TEXT, ARRAY[922]::BIGINT[]),
    (203::BIGINT, 'El curso puede llegar a ser algo pesado; la profe realmente brinda las herramientas de preparación, aunque sus clases son básicamente como si usted leyera el libro. Califica de buena manera, tiene carácter fuerte pero es buena nota. A veces tira comentarios graciosos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2023-11-19T00:00:00+00:00'::TIMESTAMPTZ, '639956708fe53f19af2f7e988abfcf4127d921b3b79e12f722d1a5409f406a13'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Física III es un curso bastante entendible independientemente de el profe. Si matricula con ella las evaluaciones van a ser sencillas y no hay como perder puntos a menos de que no vaya a clases. Vea los videos de la cátedra y le va a ir bien.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-11-17T00:00:00+00:00'::TIMESTAMPTZ, '1e387e6096cf22734e9a8de5fc9c49055206a67c90876440007a4c8bdaa3789d'::TEXT, ARRAY[922]::BIGINT[]),
    (203::BIGINT, 'En física 3 al menos la ventaja es que califica bastante suave, sin embargo sus clases es ella repitiendo lo mismo que sale en el libro, a veces llegaba tarde y se notaba poco interés en dar las mismas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2023-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'ede43e3e7874007cf6edf19149071a02b6252db6f379ad5126ac3b02db6d55b5'::TEXT, ARRAY[922]::BIGINT[]),
    (203::BIGINT, 'Las evaluaciones las hace fáciles y las califica suave. No explica muy bien la materia de clase y a veces se enreda. Es seria y no tiene muy buen trato pero si le pide ayuda, si la brinda. Con asistir y entregar todo pasa.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '2bcd9de22defce24194c11aac83704be0c19abf417a9a7ea90a6a29ae3c72c25'::TEXT, ARRAY[631]::BIGINT[]),
    (203::BIGINT, 'Lo único que hay que reconocer es que los ejemplos que enseña son bastante parecidos al examen, y además que ayuda si uno le pide. Más allá de eso, casi no se le entiende, llega tarde y nunca parece tener ganas de estar ahí. Si el curso el virtual NO MATRICULE. Si es presencial, ud debe ser autodid'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, '15bada1c59e1d6672d29937d394a9675b2d0c8e0b0dc33c399b228d68599b4bc'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'La profe es un poco vaga para explicar, llega tarde a clases y explica problemas que están resueltos en internet. Fui solo 1 mes a clases y luego empece a estudiar sola, ahorraba mi tiempo y le sacaba más provecho. Algo positivo es que contesta muy rápido por teams y siempre ayuda en lo que puede.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-11T00:00:00+00:00'::TIMESTAMPTZ, '2ae980ca39f4f33a31f32393bd53c7788095f6102b1475a2faeacafb1a901608'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Siendo honesto, es algo "floja" o vaga en algunas de las clases para explicar ejercicios (Cuando ya se pone a hacer ejercicios, la teoría si la explica bien), pero es buena opción que no van a tener clases que son tanta gastada de tiempo. Esté al día y le irá bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2022-09-02T00:00:00+00:00'::TIMESTAMPTZ, 'f0e0c9f4544296aae6ec178ca52178048c3548418ce2279cfd103521b71b8b7d'::TEXT, ARRAY[922]::BIGINT[]),
    (203::BIGINT, 'Esta clase la pasé porque los quices estaban en Internet. Un curso ya por si dificil en el cual las clases con esta profe no ayudaron mucho. Si no tiene opción, metala porque ella es buena gente. Pero lo más seguro es que tengas que llevar tutorías o buscar videos. No muy buenos ejercicios en clase'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, '2622a4d0da6fc7e504dde60a03f4642f7811398bed8448231f98995195d38250'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Fisica 2 es un curso complicado pero virtual es mas llevadero, Ella es buena gente pero a veces no se le entienden algunas cosas asi que solo vaya al dia con la materia y vea los videos de ejercicios que hace la profe ya que son muy utiles.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '3862be7b70b72bce8f5e07db2035ec26e524af680b33d60a435ff4d34671e7c0'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'No la recomiendo para F2, pero en F3 es un amor, explica súper bien la materia, hace chistes en clase, si hay gente que le responda en las clases pueden terminar saliendo hasta 30min antes, y siempre hace ejercicios difíciles para llegar preparado a los trabajos de cátedra también califica suave :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '4d487666d29d9f72880d731a3a7cc8a74190ad93cda7cec9846513ad079dcff7'::TEXT, ARRAY[922]::BIGINT[]),
    (203::BIGINT, 'Física II es un curso en el que no hay muy buenos profes. Jennifer no es mala profe pero tampoco es buena, a veces la clase se enreda un poco y suelen ser largas, aun así, es de las mejorcillas opciones en este curso. En cuanto a evaluaciones, se pasa relativamente fácil'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '2648b21b48c0547efe0c292489a11a737d31fb71978250af6771a785eec00dfd'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Las clases virtuales han sido las más malas en las que he estado, nada fluido y no se le entiende nada. Si lo lleva con compas, puede llevarlo con ella, pero si lo lleva sol@, mejor no lo meta con ella, porque no creo que prospere.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '9ef4af343e0fde862f5501305f61b3e4ede37c5382204cae02c727b8fd76ba46'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, '2414b587772449687af6d8df8bed4fc6c2ac0c93ab1dba2becf87f66f7ef46a4'::TEXT, ARRAY[922]::BIGINT[]),
    (203::BIGINT, 'Deje de asistir a sus clases como en semana 5 porque no le entendía nada, aunque física ll es un curso difícil, hay que aprender mediante la cátedra. Califica suave y se puede pasar el curso.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, '1abd70e3d8010e27adb20432bb223fabf3aeca0a06c45d0581eccaec352c3d4d'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Bastante ralita, explica muy mal y muchas veces parece que ni ella entiende la materia. Es increíble que ella sea la coordinadora de la cátedra y supuestamente ella es de lo mejor que hay. Las clases solo sirven para confundir más la materia.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'c7bc56ad77bdf4ca51c679a590dd3859272a12c0e0166bd5c95cadc42e48a908'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Tiene una manera de explicar muy extraña. Se pega, no conoce bien de la materia y además no tiene el don de la enseñanza, la ventaja es que con la virtualidad solo hay que hacer lo dela cátedra, así que dele sin miedo y aprenda solito.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '1947e3f25f9214faf47402666ad0fd5b649ccce4f60e5a83823bba64b780a271'::TEXT, ARRAY[922]::BIGINT[]),
    (203::BIGINT, 'Física II es un curso difícil, las clases no son buenas. Lo mejor es ver todo lo de cátedra y no es necesario asistir a clases. Comparado con otros profes, es buena opción, califica suave. Debe estudiar por su cuenta, pero la profe es buena gente.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'fc8ff7150a6c25b69e149f45c1552eb5163b40cee757e03a79e46b03124ee17b'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'En general es una profe que explica muy mal y para empeorar física 2 ya de por si es complicado, pero se debe decir que es lo mejor que hay en comparación con otros profes para este curso, sus quizás son fáciles y califica suave. En general si desea pasar es una opción aceptable.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ce20b8952652c1d694066c7330311ecd7630636c3fd5b9dc84d489b8f6252139'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'no lo haga compa, es una pesíma profesora'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2021-05-16T00:00:00+00:00'::TIMESTAMPTZ, '9f273f02a6f33c30d6d04c92c79bb4c49eecfdb71597ac361840c07bb361f744'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Siempre está dispuesta a ayudar o resolver dudas. Califica suave y se preocupa porque el estudiante entienda lo que está haciendo. Las pruebas cortas son bastante fáciles. El único problema es que las evaluaciones son distintas al resto de grupos, por lo que no se puede comparar mucho con los demás.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '6b0a85404c59a48cd0653cd0179c8bb500128200e3e8385ffe697297bf6f58d2'::TEXT, ARRAY[631]::BIGINT[]),
    (203::BIGINT, 'Es una buena profesora, siempre estádispuesta a ayudar al estudiante. Las clases son cómicas y hace su mejor esfuerzo para explicar. Es un 100 como persona y califica suave'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'ef92dbd216292b49cfc5ae6c134065381467e96e91bd67a6d2fe0794f554d7f5'::TEXT, ARRAY[631]::BIGINT[]),
    (203::BIGINT, 'Todas las semanas daba la clase para explicar, califica super suave, todo super chill; además, es toda vacilona. Si quiere *aprender* lab de verdad, hay mejores profes, pero para quitarse lab de encima, todo bien'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2020-12-22T00:00:00+00:00'::TIMESTAMPTZ, '3c1477cf4ffb21fd720318be5c52a19cc82762a201c6986b97c14285ed5570f3'::TEXT, ARRAY[631]::BIGINT[]),
    (203::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-29T00:00:00+00:00'::TIMESTAMPTZ, '1643a07f3232f94043c059775ec701f3ad6a3ef724fae0d738754460195c8c26'::TEXT, ARRAY[922, 630, 604]::BIGINT[]),
    (203::BIGINT, 'Para virtual fue muy buena profe, porque calificaba suave. Tal vez en las explicaciones no era la mejor.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-11T00:00:00+00:00'::TIMESTAMPTZ, '36e8eed0895ee46e9a8c5115864e849d3f7719f3e2b5ef9b086ff6303e6221ee'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Ha sido la profesora mas mala que he tenido en 4 años de estar en el TEC, explica como por encimita, parece que ni siquiera domina la materia, cuando algún compañero o compañera le consulta algo, su respuesta es un “ajá”, es realmente pésima. Ni se les ocurra matricular con ella ninguna física'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-10T00:00:00+00:00'::TIMESTAMPTZ, '5e61166959d49c130a569c9df51d1e5dd57faebf52fc63d85386c92930b17b51'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Es buena profesora, no la mejor pero es buena. Fue muy flexible en la pandemia'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, 'fbb9b3a27e2bf045944d2502af9281187b3ca5bdec805058a608e8e28d89e364'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Es de los pocos profes que explicaron la materia en modalidad virtual, por lo que me contaron de otros profes. Prepara una presentación sobre el tema y la explica por Zoom. La cátedra sube una guía con la que se pasan todas la evaluaciones. La profe responde dudas siempre y es muy muy pura vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2020-09-02T00:00:00+00:00'::TIMESTAMPTZ, '05137109df79a23622bc656ba8f3043e563b4a3f35bcb3a1fd6ea56e0b5700f8'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'Hacia una clase para aclarar dudas por semana y para calificar es muy justa. Por como se organizo la cátedra con entregar todas las tareas y actividades se pasa.Sin embargo las clases presenciales eran un poco confusas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, '41e3c44be47e349e37e7374a8cfa6397a9da283b59680432b656e5f68daa8c2c'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'db5a68dd6c2fa2dae8a254a1b90a9f9243bbc394f0e0d1de53a44b3d5df31439'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'Todo le vale, es muy artista pero prepárese para estudiar solo/sola prácticamente. En la modalidad virtual sí o sí tiene que aprender a ser auto dictáctic@ por la manera en que la escuela está dando la materia. No se aprende mucho pero se pasa fácil porque califica suave las evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '01a10a3c3f1c2632006d8a148460c938e9832e1550c25eab68c34c98256b50e6'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Un poco despistada. A veces se enreda sola. El curso virtual es regalado con cualquier profe.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'ac5f9bd75c323587472ef0a2d0ea4b6604d81e6a73c3945fdaf450c9093a17ac'::TEXT, ARRAY[631]::BIGINT[]),
    (203::BIGINT, 'Muy buena profe, la recomiendo bastánte ya que hace el curso muy ameno y explica lo necesario, es una gran persona, su personalidad es super carga.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '1096b363e1ab89ece57ac958f5c1e4fd2d9e52fbd01594ceecd931644e7b0350'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'Buena profesora, este semestre fue asincrónico y el material era bastante entendible, ella hace una sesión por semana para dudas pero creo que prefiere dar clase sincrónica. Califica justo las evaluaciones y se preocupa por la accesibilidad de todos a los medios. Recomendada'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '58b4f50ba9c0bcea2376505e5caa6b52da2a5f1ab9ab677dfcad12c55296d7ea'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Califica muy suave. Virtual da una mini clase semanal en la que explica un poco de la práctica. Hay mejores, pero no es una mala opción para pasar fácil.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '631fd3ca32153c0c0cf9a925e7a34fd5042a8cf9e5140623272f1e57785a9afa'::TEXT, ARRAY[631]::BIGINT[]),
    (203::BIGINT, 'Parece que le da igual la vida xD Si le interesa aprender, esta no es su profe, no explica apenas nada y uno tiene que ver cómo se la juega. Califica bastante suave y se pasa fácil. No es mala opción si sólo le interesa pasar.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'e624986c9439b75958ff03d437be25e56298c7f53cbb67cc50e255327e8c27ca'::TEXT, ARRAY[631]::BIGINT[]),
    (203::BIGINT, 'Llevé el curso de manera virtual,fácil si se tienen buenas bases de la materia, la profe daba clases que no eran muy útiles y la verdad se le notaba que no le agradaba dar las clases.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, 'e5cdf936e7979531cf3f252af52dfe0f4b6d1f928f9c7157d8afa7b282473b3f'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'En la modalidad virtual, fue bastante deficiente. Las "clases" que daba eran bastante malas, dado que no tenía un buen control sobre los medios virtuales, y tampoco mostró interés en aprender a mejorar. Finalmente, no se preocupó por el aprendizaje de los estudiantes. Mejor matricular con otro profe'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'f491ca27aa3243172b3ac80805df6ef8bfc29c0bb89bc39f648961911e38220f'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Llevé el curso de manera virtual con ella'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, '8625b3f12e94a8ee49e45985fe0b81776bd10a128e0f92a4b39d23d9750b3bc0'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'c5634c46eeffeac3795bc033bf1b881286fe859759afa04c9bfce68ef4af75bf'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'Es un amor de persona. Deja pocos quizes y son en el Tecdigital. Hace el curos menos pesado. Literal regala un 10%. Explica bien, se puede estudiar con los ejercicios hechos en clase y examenes viejos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-01T00:00:00+00:00'::TIMESTAMPTZ, '5a73aa4944e4d44a6ca13c1b8b8bfe12da792bdcd85d2400b3359006d008da4e'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'súper divertida y chistosa, le encanta hacer ejemplos prácticos con las personas que no comprendieron cierto tema, explica bien la materia y se devuelve a explicar si no se entendió la materia'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-18T00:00:00+00:00'::TIMESTAMPTZ, '6c00c09b15eb1fdc1707d330172023f5766fbb56b5aff51f7184ed0b141f06eb'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'No es la mejor, pero tampoco la peor, hace ejemplos del libro por lo que no siempre son lo mejor para estudiar, ayuda a la hora de entender, para el examen estudie de examenes anteriores. Califica muy muy suave y las clases son relax. Tiene preferencia por alumnos'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'e73f4b49235dd8c9373230ccea71967999680c5159dc2fdb82c4f541d6392f23'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (203::BIGINT, 'Excelente profesora, explica bien, ayuda mucho si usted le pone al curso. Hay un 10 % de la nota que prácticamente lo regala en física 2 como tareas de investigación. Hace el curso un poco menos pesado de lo que es'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Pocos exámenes']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, '30d26165aed8d38c32cfc27a2c8e15fdf88f02f2583731014e38baf091084998'::TEXT, ARRAY[630]::BIGINT[]),
    (203::BIGINT, 'Al inicio no te la tomarás en serio, ni a la profe ni al curso, sin embargo, si hay que ponerle un poquito. Realmente no es nada difícil, pero si hay que trabajar. La profe es buena persona pero parece que no se da a respetar mucho porque pocas veces alza la voz o pide atención. Recomendada para lab'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2019-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'a7f5fd92b407cce9a46a006897484e49ae0cb1b222a63d24d81b1b22c63b52ea'::TEXT, ARRAY[607]::BIGINT[]),
    (203::BIGINT, 'Tiene demasiada preferencia por estudiantes y no se preocupa por el aprendizaje de los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-10-17T00:00:00+00:00'::TIMESTAMPTZ, '661692005403b89ca148d7d5ce84d9c631307fd1d5fbb07e1ae8a2bf14dcce82'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'eee081b4ed9df08a0b8e6bce122085414b94c08186b54969fc7c976a96e08170'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (203::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '89b4e22b3f612dc6dee4924da51a7316100152633e5b7322f504713de79902ae'::TEXT, ARRAY[604]::BIGINT[]),
    (203::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-28T00:00:00+00:00'::TIMESTAMPTZ, '913d956fed01562b950e1bb92f373796fa6f4984acdb105b9d07683711c3526f'::TEXT, ARRAY[604]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
